// Search around a finite position or around an existing entity's current position on a nonempty surface. Radius must be greater than 0 and at most 1000; limit is 1 through 10000 and offset is zero-based.
type NearbyInput struct {
	Surface  *string        `json:"surface,omitempty"`
	Position *PositionInput `json:"position,omitempty"`
	// Anchors the scan on an existing entity's current position, resolved on the input surface (default nauvis); the entity must exist on that surface. When unitNumber is set, position is ignored, because the input defaults make an omitted position indistinguishable from an explicit {x: 0, y: 0}. Prototypes that carry no unit number (trees, rocks, resources, items, fish, cliffs) cannot be anchored this way and still need position.
	UnitNumber *string  `json:"unitNumber,omitempty"`
	Radius     *float64 `json:"radius,omitempty"`
	// Prototype name filter (exact).
	Name *string `json:"name,omitempty"`
	// Entity type filter (engine type such as inserter or container, not a prototype name); an unknown type is an error.
	Type *string `json:"type,omitempty"`
	// Optional force filter. Rows always carry Entity.force, so an unfiltered scan can still tell own, neutral, and enemy entities apart.
	Force  *string      `json:"force,omitempty"`
	Order  *NearbyOrder `json:"order,omitempty"`
	Offset *int         `json:"offset,omitempty"`
	Limit  *int         `json:"limit,omitempty"`
}

// Surface, force and prototype must exist. direction is 0 through 15. maxRadius is greater than 0 and at most 512 tiles, measured from origin to the candidate center. minDistanceFromEntities is 0 through 64 tiles of clear space between the footprint and any built entity or ghost of any force; natural entities (resources, trees, rocks, cliffs), characters, corpses and items never count.
type NearestPlacementInput struct {
	Surface   string         `json:"surface"`
	Force     string         `json:"force"`
	Prototype string         `json:"prototype"`
	Direction int            `json:"direction"`
	Origin    *PositionInput `json:"origin"`
	MaxRadius float64        `json:"maxRadius"`
	// Reject footprints that overlap a resource entity.
	AvoidResources bool `json:"avoidResources"`
	// Reject footprints that overlap a water tile.
	AvoidWater              bool     `json:"avoidWater"`
	MinDistanceFromEntities *float64 `json:"minDistanceFromEntities,omitempty"`
	// Require the footprint to touch the supply area of an electric pole of the force.
	RequirePowerCoverage bool `json:"requirePowerCoverage"`
	// Require a water tile within one tile of the footprint.
	RequireWaterAdjacency bool `json:"requireWaterAdjacency"`
	// Require this resource prototype inside the prototype's mining area; needs a mining drill prototype that exposes mining_drill_radius.
	RequireResource *string `json:"requireResource,omitempty"`
	// Minimum number of resource entities that must sit inside the mining area; omitted or 0 means 1, at most 100000, and only valid together with requireResource.
	MinResourceTiles *int `json:"minResourceTiles,omitempty"`
}

