type PlacementCandidate struct {
	Tick      float64 `json:"tick"`
	Surface   string  `json:"surface"`
	Force     string  `json:"force"`
	Prototype string  `json:"prototype"`
	Direction int     `json:"direction"`
	// False means every candidate center within maxRadius was rejected (expanded counts them); it does NOT mean the origin is blocked. blockers, terrain and tile below always describe the snapped origin only, so a not-found result with blockers is still just 'nothing legal within the radius'. Raise maxRadius (at most 512) to search further.
	Found bool `json:"found"`
	// Center of the nearest legal placement; null when none was found.
	Position *Position `json:"position,omitempty"`
	// Euclidean distance from origin to position; null when none was found.
	Distance *float64 `json:"distance,omitempty"`
	// Prototype names colliding with the snapped origin, sorted; empty when the engine accepts the origin.
	Blockers []string `json:"blockers"`
	// True when the ground tile under the snapped origin itself blocks the prototype.
	Terrain bool `json:"terrain"`
	// Ground tile name under the snapped origin.
	Tile string `json:"tile"`
	// Candidates evaluated, including the winner.
	Expanded int `json:"expanded"`
	// Resource entities of requireResource inside the winning candidate's mining area; 0 when no resource was required.
	ResourceTiles int `json:"resourceTiles"`
	// Total amount of requireResource inside the winning candidate's mining area; 0 when no resource was required.
	ResourceAmount float64 `json:"resourceAmount"`
}

// One placement position with canonical engine direction from 0 through 15 (0=north, 4=east, 8=south, 12=west); for an inserter the direction is the pickup side, so the drop is the opposite tile.
